"contenttype":"jsjQuery","contents":"document.addEventListener('ESignTxnCompletedWithNotification_Hold', (event) => {
 window.latestNotification = event.detail.notification;
 document.querySelector("[data-button-id*='HoldSlideout_AfterSubmitButton']").click();
});

// List of event types that use the same handler
const eventTypes = [
 "ESignTxnCompletedWithNotification_Hold"
];

const handleESignTxnCompleted = (event) => {
 window.latestNotification = event.detail.notification;
 document.querySelector("[data-button-id*='HoldActivity_AfterSubmitButton']").click();
};

// Register each event type with the same handler
eventTypes.forEach(type => {
 document.addEventListener(type, handleESignTxnCompleted);
});","contentsPath":"","onclickmf":"","documentation":"","refreshOnContextChange":false,"refreshOnContextUpdate":false,"encloseHTMLWithDiv":true
